import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonOutput
import groovy.json.JsonSlurper

// cpictl script test flow: generated by `cpictl test scripts cases --online` for one script
// and function, deployed for the run and deleted afterwards.
//
// Sets the case's headers and properties (header CpictlCase = {"headers":{...},"properties":{...}};
// HTTP header names lose their case on the way) and remembers what the message held before the
// script under test runs, so that the last step reports only what the case set or the script
// changed.

def Message processData(Message message) {
    def spec = message.getHeaders().get("CpictlCase")?.toString()
    message.getHeaders().remove("CpictlCase")
    def c = spec ? new JsonSlurper().parseText(spec) : [:]
    (c.headers ?: [:]).each { k, v -> message.setHeader(k.toString(), v == null ? "" : v.toString()) }
    (c.properties ?: [:]).each { k, v -> message.setProperty(k.toString(), v == null ? "" : v.toString()) }
    def str = { v -> v == null ? null : v.toString() }
    def headers = [:]
    message.getHeaders().each { k, v -> if (!(c.headers ?: [:]).containsKey(k)) headers[k] = str(v) }
    def props = [:]
    message.getProperties().each { k, v -> if (!(c.properties ?: [:]).containsKey(k)) props[k] = str(v) }
    message.setProperty("CpictlBaseline", JsonOutput.toJson([headers: headers, properties: props]))
    return message
}
